cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

__device__ __forceinline__ float gelu_scalar_fn(float x) {
    const float c = 0.7978845608028654f; // sqrt(2/pi)
    float x3 = x * x * x;
    float inner = c * (x + 0.044715f * x3);
    // Fast tanh via __expf intrinsic: tanh(z) = 1 - 2/(exp(2z)+1)
    float e = __expf(-2.0f * fabsf(inner));
    float t = (1.0f - e) / (1.0f + e);
    t = copysignf(t, inner);
    return 0.5f * x * (1.0f + t);
}

// Vectorized GELU kernel operating on float4 elements, using CuTe
// for global memory tensor representation, tiling, and partitioning.
template <int Threads>
__global__ void gelu_kernel_vec4(const float* __restrict__ X,
                                  float* __restrict__ Y,
                                  int N4) {
    // Direct float4 pointer views avoid constructing CuTe Tensor objects
    // inside the hot loop, reducing per-iteration register/instruction
    // overhead while keeping fully coalesced 128-bit accesses. Reads use
    // __ldg to route through the read-only cache path.
    const float4* __restrict__ X4 = reinterpret_cast<const float4*>(X);
    float4* __restrict__ Y4 = reinterpret_cast<float4*>(Y);
    // Grid-stride loop: each thread processes multiple float4 super-elements,
    // amortizing kernel launch overhead and allowing a smaller, occupancy-friendly
    // grid to cover arbitrarily large N4 while keeping accesses coalesced.
    const int stride = gridDim.x * Threads;
    // Register-blocked grid-stride loop: each outer iteration advances by
    // stride*4, and the inner unrolled loop processes 4 float4 super-elements
    // per thread, improving instruction-level parallelism and amortizing
    // loop-control overhead relative to elements processed.
    for (int base = blockIdx.x * Threads + threadIdx.x; base < N4; base += stride * 4) {
        #pragma unroll
        for (int u = 0; u < 4; ++u) {
            int idx4 = base + u * stride;
            if (idx4 < N4) {
                float4 v = __ldg(&X4[idx4]);
                float4 out;
                out.x = gelu_scalar_fn(v.x);
                out.y = gelu_scalar_fn(v.y);
                out.z = gelu_scalar_fn(v.z);
                out.w = gelu_scalar_fn(v.w);
                __stcs(&Y4[idx4], out);
            }
        }
    }
}
// Scalar fallback kernel for leftover (non-multiple-of-4) elements.
__global__ void gelu_kernel_scalar(const float* __restrict__ X,
                                    float* __restrict__ Y,
                                    int offset, int count) {
    const int stride = gridDim.x * blockDim.x;
    for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < count; i += stride) {
        int idx = offset + i;
        __stcs(&Y[idx], gelu_scalar_fn(X[idx]));
    }
}
torch::Tensor gelu_forward(torch::Tensor x) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
    auto x_c = x.contiguous();
    auto y = torch::empty_like(x_c);
    int64_t N = x_c.numel();
    int64_t N4 = N / 4;
    int64_t rem = N % 4;
    const float* xptr = x_c.data_ptr<float>();
    float* yptr = y.data_ptr<float>();
    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
    if (N4 > 0) {
        // Use a smaller thread block (256) to improve SM occupancy while
        // keeping the grid large enough to fully saturate the GPU via
        // the existing grid-stride loop.
        constexpr int Threads = 256;
        int64_t neededBlocks = (N4 + Threads - 1) / Threads;
        // Query the device for the actual number of SMs and the maximum
        // number of concurrently resident blocks per SM for this kernel
        // (via the CUDA occupancy API) instead of using a fixed, hand-picked
        // block cap. This yields a grid size that matches the hardware's
        // true occupancy limit, avoiding both under-subscription (idle SMs)
        // and over-subscription (extra scheduling/tail overhead) that a
        // static cap like 8192 can cause across different GPUs/problem sizes.
        int device = 0;
        cudaGetDevice(&device);
        int numSMs = 0;
        cudaDeviceGetAttribute(&numSMs, cudaDevAttrMultiProcessorCount, device);
        int blocksPerSM = 0;
        cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocksPerSM, gelu_kernel_vec4<Threads>, Threads, 0);
        int64_t occupancyBlocks = (int64_t)numSMs * (int64_t)(blocksPerSM > 0 ? blocksPerSM : 1);
        int64_t cappedBlocks = neededBlocks < occupancyBlocks ? neededBlocks : occupancyBlocks;
        if (cappedBlocks < 1) cappedBlocks = 1;
        dim3 block(Threads);
        dim3 grid((unsigned)cappedBlocks);
        gelu_kernel_vec4<Threads><<<grid, block, 0, stream>>>(xptr, yptr, (int)N4);
    }
    if (rem > 0) {
        int offset = (int)(N4 * 4);
        constexpr int Threads = 32;
        int64_t neededBlocks = (rem + Threads - 1) / Threads;
        int64_t cappedBlocks = neededBlocks < 256 ? neededBlocks : 256;
        dim3 block(Threads);
        dim3 grid((unsigned)cappedBlocks);
        gelu_kernel_scalar<<<grid, block, 0, stream>>>(xptr, yptr, offset, (int)rem);
    }
    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "gelu kernel launch failed: ", cudaGetErrorString(err));
    return y;
}
